def green_cases(records, expected, child_pid):
    by_name = {Path(row['pin']['path']).name: row['data'] for row in records}
    if set(by_name) != {hashlib.sha256(node.encode()).hexdigest() + '.json' for node in expected}:
        raise ValueError('exact nine case identities required')
    for node in expected:
        value = by_name[hashlib.sha256(node.encode()).hexdigest() + '.json']
        family = node.split('::')[-1].split('[')[0]
        backend = 'memory' if node.endswith('[memory]') else 'sqlite'
        second = family == 'test_late_binding_rejects_public_writer_second_connection'
        mode = ('race' if family.startswith('test_late_binding_') else
                'before' if family == 'test_writer_committed_before_binding_is_legacy' else
                'negative' if family == 'test_bound_negative_cancellation_remains_supported' else 'unbound')
        if value['backend'] != backend or value['mode'] != mode:
            raise ValueError('case backend/mode differs from frozen selected node')
        if mode == 'unbound':
            if (value['binding'] is not None or value['polled'] is not False
                    or value['worker_active_job_id'] != '' or value['before'] == value['first']
                    or value['first'] == value['after']):
                raise ValueError('real unbound legacy two-write control incomplete')
            continue
        if (value['second_connection'] is not second or value['bootstrap_complete'] is not True
                or value['exit_exception'] is not None
                or value['bootstrap']['transaction']['phase'] != 'COMPLETE'
                or value['binding'] != value['bootstrap']['original_time']
                or set(value['complete_receipts']) != {'event', 'job'}
                or any(not any(row['phase'] == 'COMPLETE' for row in group)
                       for group in value['complete_receipts'].values())):
            raise ValueError('genuine private binding and both actual COMPLETE receipts required')
        order = value['order']
        if (not order or [row['sequence'] for row in order] != list(range(1, len(order) + 1))
                or any(row['pid'] != child_pid or type(row['thread']) is not int
                       or type(row['native_thread']) is not int for row in order)):
            raise ValueError('actual ordered case child/thread provenance required')
        kinds = [row['kind'] for row in order]
        complete = kinds.index('DURING_EPISODE_GENUINE_BINDING_AND_BOTH_COMPLETE')
        if mode == 'race':
            writer = value['writer']
            error = writer['exception']
            if (value['writer_joined'] is not True or writer['attempted'] is not True
                    or writer['returned'] is not False or type(error) is not dict
                    or error['type'] != 'ValueError'
                    or not any(word in error['message'] for word in ('private', 'operational', 'scope'))
                    or value['legacy_before'] != value['legacy_after']
                    or not kinds.index('ORIGINAL_SAVE_STATE_AFTER_PUBLIC_PRECHECK_BEFORE_INNER_LOCK') < complete
                    < kinds.index('ORIGINAL_WRITER_RELEASED_TOWARD_REAL_INNER_LOCK')
                    < kinds.index('WRITER_RAISED')):
                raise ValueError('late writer private fence/order/unchanged legacy control incomplete')
        elif mode == 'before':
            writer = value['writer']
            if (value['writer_joined'] is not True or writer['returned'] is not True
                    or writer['exception'] is not None or value['legacy_before'] == value['legacy_after']
                    or kinds.index('LEGACY_WRITER_FINISHED_BEFORE_BINDING') >= complete):
                raise ValueError('genuine legacy writer-before-binding positive control incomplete')
        elif (value['negative_state'] != 'CANCELLED' or value['legacy_before'] != value['legacy_after']
              or value['bootstrap']['payload']['state'] != value['unchanged_budget']
              or kinds.index('BOUND_EXACT_NEGATIVE_CANCELLATION') <= complete):
            raise ValueError('exact negative cancellation/state/budget control incomplete')

import stat
import subprocess
import time
import xml.etree.ElementTree as ET

def index(directory):
    result = []
    if not directory.exists():
        return result
    for base, dirs, files in os.walk(directory, followlinks=False):
        for name in sorted(dirs + files):
            path = Path(base) / name
            info = path.lstat()
            row = {'path': str(path), 'mode': info.st_mode, 'bytes': info.st_size}
            if stat.S_ISLNK(info.st_mode):
                row.update(kind='symlink', target=os.readlink(path), sha256=None)
            elif stat.S_ISREG(info.st_mode):
                database = path.suffix in {'.db', '.sqlite', '.sqlite3'} or path.name.endswith(('-wal', '-shm', '-journal'))
                row.update(kind='regular', sha256=None if database else file_pin(path)['sha256'],
                           database_bytes_read=False if database else None)
            else:
                row.update(kind='directory' if stat.S_ISDIR(info.st_mode) else 'special', sha256=None)
            result.append(row)
    if len(result) > 10000:
        raise ValueError('finite evidence index cap exceeded')
    return result


def cleanup(process):
    notes = []
    deadline = time.monotonic() + 15
    try:
        os.killpg(process.pid, 0)
        remaining = True
    except ProcessLookupError:
        remaining = False
    if remaining:
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            pass
        try:
            process.wait(timeout=max(0.01, min(7, deadline - time.monotonic())))
        except subprocess.TimeoutExpired:
            notes.append('leader remained after TERM')
        try:
            os.killpg(process.pid, 0)
        except ProcessLookupError:
            remaining = False
        else:
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                pass
            process.wait(timeout=max(0.01, deadline - time.monotonic()))
            while time.monotonic() < deadline:
                try:
                    os.killpg(process.pid, 0)
                except ProcessLookupError:
                    remaining = False
                    break
                time.sleep(0.01)
    else:
        process.wait(timeout=max(0.01, deadline - time.monotonic()))
    return {'leader_reaped': process.returncode is not None,
            'group_remaining': remaining, 'cleanup_notes': notes}

